import{_ as a}from"./chunks/knowledge-base.Co7nYv_M.js";import{_ as e,o,c as r,ai as l}from"./chunks/framework.C33Uq6m-.js";const m=JSON.parse('{"title":"知识库","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/knowledge-base.md","filePath":"zh/guide/knowledge-base.md"}'),i={name:"zh/guide/knowledge-base.md"};function d(n,t,s,h,c,g){return o(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="知识库" tabindex="-1">知识库 <a class="header-anchor" href="#知识库" aria-label="Permalink to &quot;知识库&quot;">​</a></h1><p>知识库页实现了一条完整的本地 RAG（检索增强生成）流水线。上传你的文档、生成嵌入、用自然语言检索 —— 全部存放在你的浏览器里。</p><p><strong>侧边栏位置：</strong> 知识库 <strong>路由：</strong> <code>/rag</code></p><p><img src="'+a+'" alt="知识库界面"></p><h2 id="什么是-rag" tabindex="-1">什么是 RAG？ <a class="header-anchor" href="#什么是-rag" aria-label="Permalink to &quot;什么是 RAG？&quot;">​</a></h2><p>RAG 是 <strong>Retrieval-Augmented Generation</strong>（检索增强生成）的缩写。它不再只依赖模型训练时学到的内容，而是把你自己文档中的相关片段喂给模型。模型随后以这些片段为上下文，给出更准确、更有依据的回答。</p><h2 id="上传文档" tabindex="-1">上传文档 <a class="header-anchor" href="#上传文档" aria-label="Permalink to &quot;上传文档&quot;">​</a></h2><p>点击<strong>上传</strong>并选择一个或多个文件。支持的格式：</p><table tabindex="0"><thead><tr><th>格式</th><th>扩展名</th><th>解析器</th></tr></thead><tbody><tr><td>PDF</td><td><code>.pdf</code></td><td>pdfjs-dist（按需加载）</td></tr><tr><td>Word</td><td><code>.docx</code></td><td>mammoth</td></tr><tr><td>纯文本</td><td><code>.txt</code>、<code>.md</code></td><td>原生</td></tr><tr><td>CSV</td><td><code>.csv</code></td><td>papaparse</td></tr></tbody></table><h2 id="处理流水线" tabindex="-1">处理流水线 <a class="header-anchor" href="#处理流水线" aria-label="Permalink to &quot;处理流水线&quot;">​</a></h2><p>上传之后，每个文档会经过三个阶段：</p><ol><li><strong>解析</strong> —— 从文件格式中提取原始文本</li><li><strong>切分</strong> —— 把文本切成互相重叠的片段（大小与重叠量可配置）</li><li><strong>嵌入</strong> —— 用你选择的嵌入模型为每个片段生成向量</li></ol><p>进度会按文档分别显示。完成后，文档状态会变为「就绪」。</p><h2 id="检索" tabindex="-1">检索 <a class="header-anchor" href="#检索" aria-label="Permalink to &quot;检索&quot;">​</a></h2><ol><li>在搜索栏中输入自然语言查询。</li><li>结果按<strong>余弦相似度</strong>排序，语义上最相关的片段排在最前。</li><li>每条结果显示： <ul><li>匹配到的文本片段</li><li>来源文档名称</li><li>相似度分数</li><li>元数据（页码、章节、字符偏移量）</li></ul></li></ol><h2 id="管理文档" tabindex="-1">管理文档 <a class="header-anchor" href="#管理文档" aria-label="Permalink to &quot;管理文档&quot;">​</a></h2><ul><li><strong>启用 / 停用</strong> —— 控制文档是否参与检索。停用的文档不会出现在结果中。</li><li><strong>删除</strong> —— 从 IndexedDB 中移除文档及其全部片段。</li><li><strong>状态指示</strong> —— 显示处理阶段（解析中、切分中、嵌入中、就绪、出错）。</li></ul><h2 id="存储" tabindex="-1">存储 <a class="header-anchor" href="#存储" aria-label="Permalink to &quot;存储&quot;">​</a></h2><p>一切都存放在浏览器内置的数据库 <strong>IndexedDB</strong> 中：</p><ul><li>零成本 —— 不需要任何外部服务</li><li>零配置 —— 开箱即用</li><li>数据留在你自己的机器上</li><li>刷新浏览器不会丢失（但清除浏览器数据会）</li></ul><h2 id="与对话的结合" tabindex="-1">与对话的结合 <a class="header-anchor" href="#与对话的结合" aria-label="Permalink to &quot;与对话的结合&quot;">​</a></h2><p>当知识库中有文档时，相关片段可以自动作为上下文加入你的对话，让模型的回答建立在你自己的数据之上。</p><h2 id="小贴士" tabindex="-1">小贴士 <a class="header-anchor" href="#小贴士" aria-label="Permalink to &quot;小贴士&quot;">​</a></h2><ul><li><strong>较小的片段</strong>（200–400 token）通常能得到更精准的检索结果。</li><li><strong>嵌入模型很重要</strong> —— 对英文文本，<code>nomic-embed-text</code> 通常表现不错。</li><li>大型 PDF 需要一些处理时间。界面会显示进度，方便你跟踪流水线。</li><li>你可以上传多个文档，并同时在所有文档中检索。</li></ul>',24)])])}const b=e(i,[["render",d]]);export{m as __pageData,b as default};
